regexes ! { stderr_filters : r"\.rs:[0-9]+:[0-9]+(: [0-9]+:[0-9]+)?" => ".rs:LL:CC" , "alloc[0-9]+" => "ALLOC" , r"unnamed-[0-9]+" => "unnamed-ID" , r"thread '(?P<name>.*?)' \(\d+\) panicked" => "thread '$name' ($$TID) panicked" , "<[0-9]+>" => "<TAG>" , "<[0-9]+=" => "<TAG=" , "(─{50})─+" => "$1" , r" +at (.*\.rs)" => " at $1" , "([0-9]+: .*)::<.*>" => "$1" , r"0x[0-9a-fA-F]+[0-9a-fA-F]{2,2}" => "$$HEX" , "alignment [0-9]+" => "alignment ALIGN" , "[0-9]+ byte alignment but found [0-9]+" => "ALIGN byte alignment but found ALIGN" , r"call [0-9]+" => "call ID" , r"\bsys::([a-z_]+)::[a-z]+::" => "sys::$1::PLATFORM::" , r"\\" => "/" , "[^ \n`]*/(rust[^/]*|checkout)/library/" => "RUSTLIB/" , r"\bsys/([a-z_]+)/[a-z]+\b" => "sys/$1/PLATFORM" , r"[^ ]*/\.?cargo/registry/.*/(.*\.rs)" => "CARGO_REGISTRY/.../$1" , "\nExpected verification time: .* ± .*" => "\nExpected verification time: [MEAN] ± [SD]" , }